pub fn unsafe_get_HMD_log() -> Option<Common::Log_Impl>
{
  unsafe {
    let value: *mut Common::Log_Impl = &mut Common::Log_Impl::default();
    if (get_HMD_log(value)) {
      return Some(*value);
    } else {
      return None;
    }
  }
}

