#[cfg(test)]
lazy_static::lazy_static! {
  // simulate the global C variables that point to the microkit shared memory regions.  In a full
  // microkit system we would be able to mutate the shared memory for out ports since they're r/w,
  // but we couldn't do that for in ports since they are read-only
  pub static ref IN_HMD_log: Mutex<Option<Common::Log_Impl>> = Mutex::new(None);
  pub static ref IN_request_log: Mutex<Option<Common::AnalysisRequest_Impl>> = Mutex::new(None);
  pub static ref IN_encrypted_response: Mutex<Option<Common::EncryptedAnalysisResponse_Impl>> = Mutex::new(None);
  pub static ref IN_zeroize: Mutex<Option<u8>> = Mutex::new(None);
  pub static ref OUT_encrypted_log: Mutex<Option<Common::StoredLogFile_Impl>> = Mutex::new(None);
  pub static ref OUT_storage_request: Mutex<Option<Common::AnalysisRequest_Impl>> = Mutex::new(None);
  pub static ref OUT_response_log: Mutex<Option<Common::AnalysisResponse_Impl>> = Mutex::new(None);
}

#[cfg(test)]
pub fn initialize_test_globals() {
  unsafe {
    *IN_HMD_log.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_request_log.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_encrypted_response.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_zeroize.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_encrypted_log.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_storage_request.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_response_log.lock().unwrap_or_else(|e| e.into_inner()) = None;
  }
}

#[cfg(test)]
pub fn get_HMD_log(value: *mut Common::Log_Impl) -> bool
{
  unsafe {
    match *IN_HMD_log.lock().unwrap_or_else(|e| e.into_inner()) {
      Some(v) => {
        *value = v;
        return true;
      },
      None => return false,
    }
  }
}

